preConditionHook:
// EL: littleOverlap = true; for kk = 0 to consecutiveBars - 1:
//       ovTop = MinList(high[kk], high[kk+1]);
//       ovBottom = MaxList(low[kk], low[kk+1]);
//       smallRange = the smaller of the two bars' high-low ranges;
//       littleOverlap = false whenever
//           ovTop - ovBottom > maxOverlapFraction * smallRange.
// EVERY pair must pass -- the all-of-N run form, not AverageBarOverlap's mean.
// The divisor is the SMALLER of the two ranges (ThinAreaLowBarOverlap and
// OverlappingBarRun use the earlier bar's range instead), so when the newer bar
// is the smaller one this rule is the stricter test.
// MinList/MaxList are ACCEPTED for tick-grid PRICE operands only
// (EL_FEATURES.md), which bar extremes are: they differ by exactly 0 or by at
// least one tick, 1e9-1e11x the 2.22e-12 relational tolerance, so whichever
// comparison the reserved word carries cannot matter and the plain ternary
// stand-in is exact (no <algorithm> among the emitted includes anyway).
// The smaller RANGE is picked with el_lt rather than MinList: a range is a
// computed operand and outside minlist's accepted scope, while an ordinary EL
// relational is VERIFIED and carries the measured tolerance -- so a tie inside
// the tolerance takes the else branch in both twins alike. Same arrangement as
// AverageBarOverlap's gap clamp.
// A product, not a quotient: EL raises a runtime divide-by-zero and a zero-range
// bar is legal data. A gap makes ovTop - ovBottom negative, which passes.
// littleOverlap persists across bars, so it is reset before the loop.
littleOverlap = true;
for (int i = 0; i < (int)consecutiveBars; ++i) {
    ovTop = high[i] < high[i + 1] ? high[i] : high[i + 1];
    ovBottom = low[i] > low[i + 1] ? low[i] : low[i + 1];
    if (el_lt(high[i] - low[i], high[i + 1] - low[i + 1])) {
        smallRange = high[i] - low[i];
    } else {
        smallRange = high[i + 1] - low[i + 1];
    }
    if (el_gt(ovTop - ovBottom, maxOverlapFraction * smallRange)) {
        littleOverlap = false;
    }
}
